/**
 * The types `save/tournaments/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    TournamentRecordSaveRow, TournamentsSaveExtract
 * depends    src/data/tournaments/types
 * used by    src/save/tournaments/index, src/save/tournaments/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import type { TournamentLeague } from '../../data/tournaments/types'

/** One tournament the player entered, as the save records it. */
export interface TournamentRecordSaveRow {
  /** The game's running tournament number. */
  number: number | null
  /** The tournament's date, ISO. */
  date: string | null
  league: TournamentLeague | null
  leagueId: number | null
  wave: number | null
  /** Final rank. 0 while the tournament is still running. */
  rank: number | null
}

export interface TournamentsSaveExtract {
  /** The league the player is in now. */
  league: TournamentLeague | null
  leagueId: number | null
  highestLeague: TournamentLeague | null
  highestLeagueId: number | null
  /** Whether the player has joined the current tournament. */
  joined: boolean | null
  /** Whether a tournament run is in progress. */
  playing: boolean | null
  /** Tournaments entered, oldest first. */
  records: TournamentRecordSaveRow[]
  warnings: string[]
}
